begin;

-- The IANA catalogue is generated by PostgreSQL on each scan. Validate the
-- distinct zones of every personal-calendar write in one scan per statement.
create function private.validate_personal_event_time_zones() returns trigger
language plpgsql set search_path = '' as $$
declare
  zones text[];
begin
  if tg_op = 'INSERT' then
    select array_agg(distinct event.time_zone) into zones from new_events event;
  else
    select array_agg(distinct event.time_zone) into zones
    from new_events event
    left join old_events prior on prior.id = event.id
    where prior.time_zone is distinct from event.time_zone;
  end if;
  if zones is not null then
    if not zones <@ array(select name from pg_catalog.pg_timezone_names) then
      raise exception 'Invalid IANA time zone' using errcode = '22023';
    end if;
  end if;
  return null;
end;
$$;
revoke all on function private.validate_personal_event_time_zones()
  from public, anon, authenticated, service_role;

drop trigger personal_time_zone on public.personal_events;
create trigger personal_time_zone_insert after insert on public.personal_events
  referencing new table as new_events for each statement
  execute function private.validate_personal_event_time_zones();
create trigger personal_time_zone_update after update on public.personal_events
  referencing old table as old_events new table as new_events for each statement
  execute function private.validate_personal_event_time_zones();

-- Keep the original identity, permissions and calendar conflict checks. A
-- repeat import must skip stored identities before the row overlap trigger.
create or replace function private.import_my_calendar(p_events jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  actor uuid := auth.uid();
  event_count integer;
  inserted integer;
  known_zones text[];
begin
  if actor is null or not private.actor_active() then raise insufficient_privilege; end if;
  if p_events is null or jsonb_typeof(p_events) <> 'array' then
    raise exception 'Invalid calendar batch' using errcode = '22023';
  end if;
  event_count := jsonb_array_length(p_events);
  if event_count not between 1 and 500 then
    raise exception 'Invalid calendar batch' using errcode = '22023';
  end if;

  known_zones := array(select name from pg_catalog.pg_timezone_names);
  if exists (
    select 1 from jsonb_array_elements(p_events) event(item)
    where jsonb_typeof(item) <> 'object'
      or length(coalesce(item->>'uid', '')) not between 1 and 1024
      or length(trim(coalesce(item->>'title', ''))) not between 1 and 200
      or length(coalesce(item->>'description', '')) > 10000
      or item->>'starts_at' is null or item->>'ends_at' is null
      or not isfinite((item->>'starts_at')::timestamptz)
      or not isfinite((item->>'ends_at')::timestamptz)
      or (item->>'ends_at')::timestamptz <= (item->>'starts_at')::timestamptz
      or not coalesce((item->>'time_zone') = any(known_zones), false)
  ) then
    raise exception 'Invalid imported appointment' using errcode = '22023';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(actor::text || ':calendar-import', 0));
  with entries as (
    select item, position, encode(sha256(convert_to(item->>'uid', 'UTF8')), 'hex') as import_key
    from jsonb_array_elements(p_events) with ordinality as event(item, position)
  ), first_occurrence as (
    select distinct on (import_key) item, position, import_key
    from entries
    order by import_key, position
  )
  insert into public.personal_events(user_id, title, description, starts_at, ends_at, time_zone, import_key)
  select actor, event.item->>'title', coalesce(event.item->>'description', ''),
    (event.item->>'starts_at')::timestamptz, (event.item->>'ends_at')::timestamptz,
    event.item->>'time_zone', event.import_key
  from first_occurrence event
  where not exists (
    select 1 from public.personal_events existing
    where existing.user_id = actor and existing.import_key = event.import_key
  )
  order by event.position;

  get diagnostics inserted = row_count;
  return jsonb_build_object('created', inserted, 'skipped', event_count - inserted);
end;
$$;

commit;
